153: static void
154: _cpuid(unsigned int cpu_info[4U], const unsigned int cpu_info_type)
155: {
156:     /*
157:      * Visual Studio has a __cpuid() intrinsic with 2 parameters,
158:      * but clang defines _MSC_VER as an incompatible __cpuid() macro
159:      * with 5 parameters, that may be defined if <cpuid.h> is
160:      * unintentionally included.
161:      */
162: #if defined(_MSC_VER) && (defined(_M_X64) || defined(_M_IX86)) && !defined(__cpuid)
163:     __cpuid((int *) cpu_info, cpu_info_type);
164: #elif defined(HAVE_CPUID)
165:     cpu_info[0] = cpu_info[1] = cpu_info[2] = cpu_info[3] = 0;
166: # ifdef __i386__
167:     __asm__ __volatile__(
168:         "pushfl; pushfl; "
169:         "popl %0; "
170:         "movl %0, %1; xorl %2, %0; "
171:         "pushl %0; "
172:         "popfl; pushfl; popl %0; popfl"
173:         : "=&r"(cpu_info[0]), "=&r"(cpu_info[1])
174:         : "i"(0x200000));
175:     if (((cpu_info[0] ^ cpu_info[1]) & 0x200000) == 0x0) {
176:         return; /* LCOV_EXCL_LINE */
177:     }
178: # endif
179: # ifdef __i386__
180:     __asm__ __volatile__("xchgl %%ebx, %k1; cpuid; xchgl %%ebx, %k1"
181:                          : "=a"(cpu_info[0]), "=&r"(cpu_info[1]),
182:                            "=c"(cpu_info[2]), "=d"(cpu_info[3])
183:                          : "0"(cpu_info_type), "2"(0U));
184: # elif defined(__x86_64__)
185:     __asm__ __volatile__("xchgq %%rbx, %q1; cpuid; xchgq %%rbx, %q1"
186:                          : "=a"(cpu_info[0]), "=&r"(cpu_info[1]),
187:                            "=c"(cpu_info[2]), "=d"(cpu_info[3])
188:                          : "0"(cpu_info_type), "2"(0U));
189: # else
190:     __asm__ __volatile__("cpuid"
191:                          : "=a"(cpu_info[0]), "=b"(cpu_info[1]),
192:                            "=c"(cpu_info[2]), "=d"(cpu_info[3])
193:                          : "0"(cpu_info_type), "2"(0U));
194: # endif
195: #else
196:     (void) cpu_info_type;
197:     cpu_info[0] = cpu_info[1] = cpu_info[2] = cpu_info[3] = 0;
198: #endif
199: }
