203: {
204:     unsigned int cpu_info[4];
205:     uint32_t     xcr0 = 0U;
206: 
207:     _cpuid(cpu_info, 0x0);
208:     if (cpu_info[0] == 0U) {
209:         return -1; /* LCOV_EXCL_LINE */
210:     }
211:     _cpuid(cpu_info, 0x00000001);
212: #ifdef HAVE_EMMINTRIN_H
213:     cpu_features->has_sse2 = ((cpu_info[3] & CPUID_EDX_SSE2) != 0x0);
214: #else
