216: #endif
217: 
218: #ifdef HAVE_PMMINTRIN_H
219:     cpu_features->has_sse3 = ((cpu_info[2] & CPUID_ECX_SSE3) != 0x0);
220: #else
221:     cpu_features->has_sse3   = 0;
222: #endif
223: 
224: #ifdef HAVE_TMMINTRIN_H
225:     cpu_features->has_ssse3 = ((cpu_info[2] & CPUID_ECX_SSSE3) != 0x0);
226: #else
227:     cpu_features->has_ssse3  = 0;
228: #endif
229: 
230: #ifdef HAVE_SMMINTRIN_H
231:     cpu_features->has_sse41 = ((cpu_info[2] & CPUID_ECX_SSE41) != 0x0);
232: #else
233:     cpu_features->has_sse41  = 0;
234: #endif
235: 
236:     cpu_features->has_avx = 0;
237: 
238:     (void) xcr0;
239: #ifdef HAVE_AVXINTRIN_H
240:     if ((cpu_info[2] & (CPUID_ECX_AVX | CPUID_ECX_XSAVE | CPUID_ECX_OSXSAVE)) ==
241:         (CPUID_ECX_AVX | CPUID_ECX_XSAVE | CPUID_ECX_OSXSAVE)) {
242:         xcr0 = 0U;
243: # if defined(HAVE__XGETBV) || \
244:         (defined(_MSC_VER) && defined(_XCR_XFEATURE_ENABLED_MASK) && _MSC_FULL_VER >= 160040219)
245:         xcr0 = (uint32_t) _xgetbv(0);
246: # elif defined(_MSC_VER) && defined(_M_IX86)
247:         /*
248:          * Visual Studio documentation states that eax/ecx/edx don't need to
249:          * be preserved in inline assembly code. But that doesn't seem to
250:          * always hold true on Visual Studio 2010.
251:          */
252:         __asm {
253:             push eax
254:             push ecx
255:             push edx
256:             xor ecx, ecx
257:             _asm _emit 0x0f _asm _emit 0x01 _asm _emit 0xd0
258:             mov xcr0, eax
259:             pop edx
260:             pop ecx
261:             pop eax
262:         }
263: # elif defined(HAVE_AVX_ASM)
264:         __asm__ __volatile__(".byte 0x0f, 0x01, 0xd0" /* XGETBV */
265:                              : "=a"(xcr0)
266:                              : "c"((uint32_t) 0U)
267:                              : "%edx");
268: # endif
269:         if ((xcr0 & (XCR0_SSE | XCR0_AVX)) == (XCR0_SSE | XCR0_AVX)) {
270:             cpu_features->has_avx = 1;
271:         }
272:     }
273: #endif
274: 
275:     cpu_features->has_avx2 = 0;
276: #ifdef HAVE_AVX2INTRIN_H
277:     if (cpu_features->has_avx) {
278:         unsigned int cpu_info7[4];
279: 
280:         _cpuid(cpu_info7, 0x00000007);
281:         cpu_features->has_avx2 = ((cpu_info7[1] & CPUID_EBX_AVX2) != 0x0);
282:     }
283: #endif
