288:         unsigned int cpu_info7[4];
289: 
290:         _cpuid(cpu_info7, 0x00000007);
291:         /* LCOV_EXCL_START */
292:         if ((cpu_info7[1] & CPUID_EBX_AVX512F) == CPUID_EBX_AVX512F &&
293:             (xcr0 & (XCR0_OPMASK | XCR0_ZMM_HI256 | XCR0_HI16_ZMM))
294:             == (XCR0_OPMASK | XCR0_ZMM_HI256 | XCR0_HI16_ZMM)) {
295:             cpu_features->has_avx512f = 1;
296:         }
297:         /* LCOV_EXCL_STOP */
298:     }
299: #endif
300: 
301: #ifdef HAVE_WMMINTRIN_H
302:     cpu_features->has_pclmul = ((cpu_info[2] & CPUID_ECX_PCLMUL) != 0x0);
303:     cpu_features->has_aesni  = ((cpu_info[2] & CPUID_ECX_AESNI) != 0x0);
304: #else
